const profile = $input.first().json.result.profile;

const query = `
CRM_INTENT: LOYAL customer optimization

OBJECTIVE:
increase_frequency + cross_sell + retention_balance

CUSTOMER:
segment=${profile.segment}
branchId=${profile.branchId}
spend=${profile.monetary90d}
frequency=${profile.frequency90d}
`.trim();

return [{ query, profile }];

const profile = $('Get User Profile').first().json.result.profile;
const segment = profile.segment;

let strategyRule = "";
let policy = {};

switch (segment) {
  case "VIP":
    strategyRule = "Ưu tiên dịch vụ cao cấp, không giảm giá mạnh, tập trung trải nghiệm.";
    policy = {
      goal: "increase_ltv",
      discountAllowed: "low",
      focus: ["service", "experience"]
    };
    break;

  case "LOYAL":
    strategyRule = "Tăng tần suất mu, ưu tiên combo và cross-sell.";
    policy = {
      goal: "increase_frequency",
      discountAllowed: "medium",
      focus: ["service", "product", "cross_sell"]
    };
    break;

  case "POTENTIAL":
    strategyRule = "Kích hoạt mua lại bằng voucher nhẹ và sản phẩm entry.";
    policy = {
      goal: "activate_conversion",
      discountAllowed: "medium_high",
      focus: ["product", "voucher"]
    };
    break;

  case "AT_RISK":
    strategyRule = "Giữ chân khách hàng bằng ưu đãi mạnh và chăm sóc dịch vụ.";
    policy = {
      goal: "reduce_churn",
      discountAllowed: "high",
      focus: ["voucher", "service"]
    };
    break;

  case "CHURNED":
    strategyRule = "Win-back bằng giảm giá mạnh và chiến dịch tái kích hoạt.";
    policy = {
      goal: "win_back",
      discountAllowed: "very_high",
      focus: ["voucher"]
    };
    break;

  default:
    strategyRule = "Chiến lược mặc định cân bằng tăng trưởng.";
    policy = {
      goal: "general_growth",
      discountAllowed: "medium",
      focus: ["service", "product", "voucher"]
    };
    break;
}

return [
  {
    strategyRule,
    policy,
    segment
  }
];

const items = $('Search Related Points').first().json.result;

const profile = $('Get User Profile').first().json.result.profile;

function score(item) {
  const p = item.payload;

  let s = item.score || 0;

  // base type logic
  if (p.type === "service") s += 0.4;
  if (p.type === "product") s += 0.2;
  if (p.type === "voucher") s -= 0.1;

  // segment logic
  if (profile.segment === "LOYAL") {
    if (p.type === "service") s += 0.3;
    if (p.type === "product") s += 0.15;
  }

  // frequency logic
  if (profile.frequency90d > 5) {
    if (p.type === "service") s += 0.2;
  }

  return s;
}

const ranked = items
  .map(i => ({
    ...i,
    businessScore: score(i)
  }))
  .sort((a, b) => b.businessScore - a.businessScore);

return [{ ranked }];

const ranked = $input.first().json.ranked;

const revenue = ranked.find(i => i.payload.type === "service");
const crossSell = ranked.find(i => i.payload.type === "product");
const retention = ranked.find(i => i.payload.type === "voucher");

const portfolio = [revenue, crossSell, retention]
  .filter(Boolean);

return [{ portfolio }];

const portfolio = $input.first().json.portfolio;

const enriched = portfolio.map((i, idx) => {
  const p = i.payload;

  let role = "unknown";

  if (p.type === "service") role = "revenue_driver";
  if (p.type === "product") role = "cross_sell";
  if (p.type === "voucher") role = "retention";

  return {
    rank: idx + 1,
    type: p.type,
    name: p.name || p.code,
    role
  };
});

return [{ enriched }];

