  "AQ.Ab8RN6KuDRJAsf7i7A_dvpysYY3xOG7LoQJFQQ_mwDsEwN474g"
];

const randomKey = apiKeys[Math.floor(Math.random() * apiKeys.length)];

return [
  {
    json: {
      ...$input.first().json,
      apiKey: randomKey
    }
  }
];
